http:request.http:body:
#[%dw 2.0
output application/json
---
{
    systemInstruction: {
        parts: [
            {
                text: "You are a terse MuleSoft integration expert. Answer in plain, simple sentences."
            }
        ]
    },
    contents: [
        {
            role: "user",
            parts: [
                {
                    text: vars.userPrompt
                }
            ]
        }
    ],
    generationConfig: {
        temperature: 0.2,
        topP: 0.9,
        topK: 40,
        maxOutputTokens: 1024,
        thinkingConfig: {
            thinkingBudget: 0
        },
        responseMimeType: "application/json",
        responseSchema: {
            "type": "object",
            properties: {
                summary: { "type": "string" },
                keyPoints: {
                    "type": "array",
                    items: { "type": "string" }
                }
            },
            required: ["summary", "keyPoints"]
        }
    }
}]
